import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import { WikiCard } from './WikiCard';
import type { WikiArticle } from './WikiCard';

const likedArticle: WikiArticle = {
  title: 'Theory of Relativity',
  displaytitle: 'Theory of Relativity',
  extract:
    'The theory of relativity usually encompasses two interrelated physics theories by Albert Einstein: special relativity and general relativity, proposed and published in 1905 and 1915, respectively.',
  pageid: 5001,
  url: 'https://en.wikipedia.org/wiki/Theory_of_relativity',
  thumbnail: {
    source:
      'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Albert_Einstein_Head.jpg/800px-Albert_Einstein_Head.jpg',
    width: 800,
    height: 600,
  },
};

const meta = {
  component: WikiCard,
  tags: ['ai-generated'],
  parameters: {
    layout: 'fullscreen',
  },
} satisfies Meta<typeof WikiCard>;

export default meta;
type Story = StoryObj<typeof meta>;

export const PreLikedArticle: Story = {
  args: {
    article: likedArticle,
  },
  async beforeEach() {
    localStorage.setItem(
      'likedArticles',
      JSON.stringify([likedArticle]),
    );
  },
  play: async ({ canvas }) => {
    const likeButton = canvas.getByRole('button', { name: /like article/i });
    // When pre-liked, the button should have bg-red-500 class
    await waitFor(() => {
      expect(likeButton.className).toMatch(/bg-red-500/);
    });
  },
};

export const UnlikeArticle: Story = {
  args: {
    article: likedArticle,
  },
  async beforeEach() {
    localStorage.setItem(
      'likedArticles',
      JSON.stringify([likedArticle]),
    );
  },
  play: async ({ canvas, userEvent }) => {
    const likeButton = canvas.getByRole('button', { name: /like article/i });
    await waitFor(() => {
      expect(likeButton.className).toMatch(/bg-red-500/);
    });
    await userEvent.click(likeButton);
    await waitFor(() => {
      expect(likeButton.className).not.toMatch(/bg-red-500/);
    });
  },
};

export const DoubleTapToLike: Story = {
  args: {
    article: {
      ...likedArticle,
      pageid: 6001,
    },
  },
  play: async ({ canvas, userEvent }) => {
    const likeButton = canvas.getByRole('button', { name: /like article/i });
    // Initially not liked
    await expect(likeButton.className).not.toMatch(/bg-red-500/);
    // Double click the card area to like
    const heading = canvas.getByRole('heading', {
      name: /theory of relativity/i,
    });
    await userEvent.dblClick(heading);
    await waitFor(() => {
      expect(likeButton.className).toMatch(/bg-red-500/);
    });
  },
};

import type { Meta, StoryObj } from '@storybook/react-vite';
import { expect, waitFor } from 'storybook/test';
import App from './App';
import type { WikiArticle } from './components/WikiCard';

const savedArticles: WikiArticle[] = [
  {
    title: 'Quantum Mechanics',
    displaytitle: 'Quantum Mechanics',
    extract: 'Quantum mechanics is a fundamental theory in physics.',
    pageid: 1001,
    url: 'https://en.wikipedia.org/wiki/Quantum_mechanics',
    thumbnail: {
      source: 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Hydrogen_Density_Plots.png/800px-Hydrogen_Density_Plots.png',
      width: 800,
      height: 600,
    },
  },
  {
    title: 'Aurora Borealis',
    displaytitle: 'Aurora Borealis',
    extract: 'An aurora is a natural light display in Earth\'s sky.',
    pageid: 1002,
    url: 'https://en.wikipedia.org/wiki/Aurora_(astronomy)',
    thumbnail: {
      source: 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Polarlicht_2.jpg/800px-Polarlicht_2.jpg',
      width: 800,
      height: 533,
    },
  },
];

const meta = {
  component: App,
  tags: ['ai-generated'],
  parameters: {
    layout: 'fullscreen',
  },
  async beforeEach() {
    localStorage.setItem('likedArticles', JSON.stringify(savedArticles));
  },
} satisfies Meta<typeof App>;

export default meta;
type Story = StoryObj<typeof meta>;

export const LikesModalWithSavedArticles: Story = {
  play: async ({ canvas, userEvent }) => {
    await waitFor(
      () => {
        expect(canvas.getByText('WikiTok')).toBeVisible();
      },
      { timeout: 5000 },
    );
    await userEvent.click(canvas.getByText('Likes'));
    await waitFor(() => {
      expect(canvas.getByText('Liked Articles')).toBeVisible();
    });
    // Saved articles should appear in the likes modal
    await expect(canvas.getAllByText('Quantum Mechanics').length).toBeGreaterThanOrEqual(1);
    await expect(canvas.getAllByText('Aurora Borealis').length).toBeGreaterThanOrEqual(1);
    // Export button should be visible when there are liked articles
    await expect(canvas.getByText('Export')).toBeVisible();
  },
};

export const SearchLikedArticles: Story = {
  play: async ({ canvas, userEvent }) => {
    await waitFor(
      () => {
        expect(canvas.getByText('WikiTok')).toBeVisible();
      },
      { timeout: 5000 },
    );
    await userEvent.click(canvas.getByText('Likes'));
    await waitFor(() => {
      expect(canvas.getByText('Liked Articles')).toBeVisible();
    });
    const searchInput = canvas.getByPlaceholderText('Search liked articles...');
    await userEvent.type(searchInput, 'Aurora');
    // Only Aurora should remain visible in the filtered list
    await waitFor(() => {
      expect(canvas.queryByText('No matches found.')).not.toBeInTheDocument();
    });
  },
};

export const SearchNoResults: Story = {
  play: async ({ canvas, userEvent }) => {
    await waitFor(
      () => {
        expect(canvas.getByText('WikiTok')).toBeVisible();
      },
      { timeout: 5000 },
    );
    await userEvent.click(canvas.getByText('Likes'));
    await waitFor(() => {
      expect(canvas.getByText('Liked Articles')).toBeVisible();
    });
    const searchInput = canvas.getByPlaceholderText('Search liked articles...');
    await userEvent.type(searchInput, 'nonexistenttopic');
    await waitFor(() => {
      expect(canvas.getByText('No matches found.')).toBeVisible();
    });
  },
};

